import Home from "./pages/Home";
import MemberInfo from "./pages/MemberInfo";
import Profile from "./pages/Profile";
import Events from "./pages/Events";
import Contacts from "./pages/Contacts";
import "./App.scss";
import "./components/SearchBar.scss";

